int main() {
    int bad = 0;
    for (const Case & c : kCases) {
        const std::string got = bl::render_dsv41(c.msgs, c.think, c.tools);
        if (got == c.want) continue;
        ++bad;
        const std::string want = c.want;
        size_t at = 0;
        while (at < got.size() && at < want.size() && got[at] == want[at]) ++at;
        std::printf("FAIL %s (think \"%s\"), first difference at byte %zu\n  want ...%s\n  got  ...%s\n", c.name, c.think, at,
                    want.substr(at > 40 ? at - 40 : 0, 120).c_str(), got.substr(at > 40 ? at - 40 : 0, 120).c_str());
    }
    std::printf("%zu cases, %d failed\n", kCases.size(), bad);
    return bad ? 1 : 0;
}
